import{_ as r,C as i,c as l,o as u,a3 as n,G as s,j as e,a as o}from"./chunks/framework.Dokpd4od.js";const T=JSON.parse('{"title":"Taxes","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/taxes/taxes.md","filePath":"master/finance/taxes/taxes.md","lastUpdated":1792041590000}'),h={name:"master/finance/taxes/taxes.md"};function c(d,t,g,p,m,x){const a=i("ImagePopup");return u(),l("div",null,[t[0]||(t[0]=n('<h1 id="taxes" tabindex="-1">Taxes <a class="header-anchor" href="#taxes" aria-label="Permalink to &quot;Taxes&quot;">​</a></h1><p>A tax tells Aureus how much to add to a line, and which accounts the tax amount is booked to. You set up each tax once, attach it to your products, and it works on every invoice and bill from then on.</p><blockquote><p><strong>In simple words:</strong> A tax is a rule: &quot;add 15 % to the price and record it in the tax account&quot;.</p></blockquote><h2 id="when-to-use-this-page" tabindex="-1">When to use this page <a class="header-anchor" href="#when-to-use-this-page" aria-label="Permalink to &quot;When to use this page&quot;">​</a></h2><ul><li>You start selling in a new country or at a new rate.</li><li>You need a fixed fee per unit, or a tax with a special formula.</li><li>You need two taxes shown as one, for example a state tax plus a city tax.</li></ul><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><ul><li>Invoices app: <code>Invoices → Configurations → Taxes</code></li><li>Accounting app: <code>Accounting → Configurations → Accounting → Taxes</code></li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows <strong>Name</strong>, <strong>Company</strong>, <strong>Tax Group</strong>, <strong>Tax Type</strong>, <strong>Invoice Label</strong> and <strong>Status</strong>. The tabs are <strong>Default</strong>, <strong>Sale</strong>, <strong>Purchase</strong>, a Service tab, <strong>Goods</strong>, <strong>Active</strong> and <strong>In active</strong>. You can also group by <strong>Name</strong>, <strong>Company</strong>, <strong>Tax Group</strong>, <strong>Country</strong>, <strong>Created By</strong>, <strong>Type Tax Use</strong>, <strong>Tax Scope</strong> or <strong>Amount Type</strong>.</p>',9)),s(a,{src:"/images1/finance/taxes_list.png",alt:"Accounting → Configurations → Accounting → Taxes list with the two sample 15 % taxes"}),t[1]||(t[1]=e("h2",{id:"create-a-tax",tabindex:"-1"},[o("Create a tax "),e("a",{class:"header-anchor",href:"#create-a-tax","aria-label":'Permalink to "Create a tax"'},"​")],-1)),t[2]||(t[2]=e("ol",null,[e("li",null,"Open the Taxes page."),e("li",null,[o("Click "),e("strong",null,"New Tax"),o(".")]),e("li",null,"Fill in the form below."),e("li",null,[o("Click "),e("strong",null,"Create"),o(".")])],-1)),s(a,{src:"/images1/finance/tax_form.png",alt:"New Tax form with Name 18 %, Tax Type Sale, Tax Computation Percent, Amount 18, and Tax Group chosen"}),t[3]||(t[3]=n('<h3 id="main-fields" tabindex="-1">Main fields <a class="header-anchor" href="#main-fields" aria-label="Permalink to &quot;Main fields&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The name you pick on products and lines, such as <code>18 %</code>. Required.</li><li><strong><em>Tax Type:</em></strong> <strong>Sale</strong>, <strong>Purchase</strong> or <strong>None</strong>. Sale taxes show on invoices and credit notes. Purchase taxes show on bills. <strong>None</strong> is for taxes that only exist to be put inside a group. Required.</li><li><strong><em>Tax Computation:</em></strong> How the amount is worked out. Required. See the list below.</li><li><strong><em>Tax Scope:</em></strong> Optional. Mark the tax as for <strong>Service</strong> or <strong>Goods</strong>. It is used to filter the list.</li><li><strong><em>Status:</em></strong> Turn on to make the tax available. Turn off to retire it without deleting.</li><li><strong><em>Amount:</em></strong> The rate in per cent, or the fixed amount in your company currency. Shows for Fixed, Percent and Division.</li><li><strong><em>Formula:</em></strong> For <strong>Custom Formula</strong> only. See below.</li><li><strong><em>Children Taxes:</em></strong> For <strong>Group</strong> only. Choose the taxes to add together.</li></ul><h3 id="tax-computation-values" tabindex="-1">Tax Computation values <a class="header-anchor" href="#tax-computation-values" aria-label="Permalink to &quot;Tax Computation values&quot;">​</a></h3><ul><li><strong>Percent:</strong> the rate is a percentage of the price. 18 on a price of 100 gives 18.</li><li><strong>Division:</strong> the rate is a percentage of the price that already includes the tax. Use it for the &quot;tax included&quot; style of rate. Price 100 with 20 gives 20.</li><li><strong>Fixed:</strong> a set amount per unit. The tax is the amount times the quantity.</li><li><strong>Group:</strong> adds up several other taxes. You cannot use another group inside a group.</li><li><strong>Custom Formula:</strong> you write the calculation yourself.</li></ul><h3 id="custom-formula" tabindex="-1">Custom formula <a class="header-anchor" href="#custom-formula" aria-label="Permalink to &quot;Custom formula&quot;">​</a></h3><p>The <strong>Formula</strong> field accepts only arithmetic: numbers, <code>+ - * / ( )</code>, the functions <code>min</code> and <code>max</code>, and these variables: <code>price_unit</code>, <code>quantity</code> and <code>price_subtotal</code>. For example <code>min(price_unit * quantity * 0.18, 500)</code> is 18 % of the line, but never more than 500. Aureus checks the formula when you save and shows an error if it is not valid.</p><h3 id="group-taxes" tabindex="-1">Group taxes <a class="header-anchor" href="#group-taxes" aria-label="Permalink to &quot;Group taxes&quot;">​</a></h3><p>For a <strong>Group</strong>, <strong>Amount</strong> is hidden. The amount is the sum of the <strong>Children Taxes</strong>. Children must have the same <strong>Tax Type</strong> as the group, or <strong>None</strong>. A group has no distribution lines of its own.</p><h3 id="advanced-options" tabindex="-1">Advanced Options <a class="header-anchor" href="#advanced-options" aria-label="Permalink to &quot;Advanced Options&quot;">​</a></h3><ul><li><strong><em>Invoice label:</em></strong> The text printed for the tax on the invoice, such as <code>VAT 18 %</code>.</li><li><strong><em>Tax Group:</em></strong> The group the tax is shown under. Required. You can create one from this field. See <a href="./tax-groups.html">Tax groups</a>.</li><li><strong><em>Country:</em></strong> The country the tax belongs to.</li><li><strong><em>Included in Price:</em></strong> <strong>Default</strong>, <strong>Included</strong> or <strong>Excluded</strong>. Choose <strong>Included</strong> when the price you enter already contains this tax. See <a href="./tax-settings.html">Tax settings</a>.</li><li><strong><em>Affect Base of Subsequent Taxes:</em></strong> Turn on so that taxes after this one are calculated on the price plus this tax.</li><li><strong><em>Base Affected by Previous Taxes:</em></strong> Turn on so that this tax is calculated on the price plus the taxes before it.</li></ul><h3 id="repartition-lines-tab" tabindex="-1">Repartition Lines tab <a class="header-anchor" href="#repartition-lines-tab" aria-label="Permalink to &quot;Repartition Lines tab&quot;">​</a></h3><p>This tab decides which accounts get the money. It shows for every type except <strong>Group</strong>. There are two tables: <strong>Invoice Repartition Lines</strong> and <strong>Refund Repartition Lines</strong>. The refund table is used on credit notes and refunds.</p><p>Each table has at least one line. A new tax starts with two lines: a <strong>Base</strong> line and an <strong>of Tax</strong> line at 100 %.</p><ul><li><strong><em>Type:</em></strong> <strong>Base</strong> is the untaxed amount. <strong>of Tax</strong> is the tax amount.</li><li><strong><em>Factor %:</em></strong> The share of the tax this line gets. For <strong>of Tax</strong> lines it is required, 0 to 100. Use several lines to split a tax across accounts.</li><li><strong><em>Account:</em></strong> The account that receives the amount. Required for <strong>of Tax</strong> lines. The <strong>Base</strong> line has no account.</li></ul><p>Pick your tax payable account on the <strong>of Tax</strong> line of the invoice table, and a tax receivable account on the purchase side.</p><h3 id="descriptions-tab" tabindex="-1">Descriptions tab <a class="header-anchor" href="#descriptions-tab" aria-label="Permalink to &quot;Descriptions tab&quot;">​</a></h3><ul><li><strong><em>Description:</em></strong> An internal note about the tax.</li><li><strong><em>Legal Notes:</em></strong> Text for legal mentions linked to the tax.</li></ul><h2 id="how-a-tax-works-on-a-line" tabindex="-1">How a tax works on a line <a class="header-anchor" href="#how-a-tax-works-on-a-line" aria-label="Permalink to &quot;How a tax works on a line&quot;">​</a></h2><p>Example: a Camping Hammock sells for 100. The tax is 15 % <strong>Percent</strong> and <strong>Excluded</strong>.</p><table tabindex="0"><thead><tr><th>Line</th><th>Amount</th></tr></thead><tbody><tr><td>Untaxed amount</td><td>100.00</td></tr><tr><td>Tax 15 %</td><td>15.00</td></tr><tr><td>Total</td><td>115.00</td></tr></tbody></table><p>When you confirm the invoice, the 15 is booked to the account on the <strong>of Tax</strong> line. The 100 goes to the income account.</p><p>If the same tax is <strong>Included</strong>, the price of 100 already contains the tax. The untaxed amount becomes 86.96 and the tax 13.04.</p><h2 id="delete-a-tax" tabindex="-1">Delete a tax <a class="header-anchor" href="#delete-a-tax" aria-label="Permalink to &quot;Delete a tax&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A tax that is in use cannot be deleted. Aureus shows &quot;Tax could not be deleted&quot;. Turn <strong>Status</strong> off instead.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./tax-groups.html">Tax groups</a></li><li><a href="./tax-settings.html">Tax settings</a></li><li><a href="./fiscal-positions.html">Fiscal positions</a></li><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li></ul>',26))])}const b=r(h,[["render",c]]);export{T as __pageData,b as default};
